```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts - The gods provide
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();
const mockItems = [
  { id: '1', name: 'Lightning Bolt', price: 99.99 },
  { id: '2', name: 'Ambrosia', price: 49.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 149.98, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - The Divine Flow', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'OLYMPUS-12345' });
  });

  // HAPPY PATH - As Zeus commands
  it('completes full checkout journey from shipping to confirmation', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    render(<Checkout onComplete={onComplete} />);

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Mount Olympus');
    await user.type(screen.getByLabelText(/city/i), 'Athens');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), '4242424242424242');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Zeus Olympios');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/lightning bolt/i)).toBeInTheDocument();
    expect(screen.getByText(/\$149\.98/)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
    });
    expect(onComplete).toHaveBeenCalledWith('OLYMPUS-12345');
  });

  // VALIDATION - None shall pass without proper tribute
  describe('Form Validation', () => {
    it('displays shipping errors for empty required fields', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // ERROR STATES - Even gods must handle failure
  it('displays payment error and allows retry', async () => {
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined by Hades'));
    const user = userEvent.setup();
    render(<Checkout />);

    // Navigate to review (abbreviated)
    // ... complete shipping and payment forms ...

    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined by hades/i);
    });
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });

  // LOADING STATES
  it('disables buttons during payment processing', async () => {
    mockProcessPayment.mockImplementation(() => new Promise(() => {}));
    render(<Checkout />);
    // Navigate to review...

    await userEvent.click(screen.getByRole('button', { name: /place order/i }));

    expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
  });

  // EDGE CASES
  it('shows empty cart message when no items', () => {
    vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
    render(<Checkout onCancel={vi.fn()} />);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  // ACCESSIBILITY - All mortals deserve access
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });
});
